<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { api, ApiError, API_BASE, streamChat } from '../../api'
import type { ChatResponse, Job, KnowledgeBase } from '../../api'
import { ArrowDown, ArrowRight, ArrowUpRight, BookOpen, CalendarDays, Check, CheckCheck, Circle, Clock3, FileText, Layers3, Lightbulb, MessageSquare, Plus, Sparkles, Target, Waypoints } from 'lucide-vue-next'
import FocusTimer from './FocusTimer.vue'
import StudyOrbit from './StudyOrbit.vue'
import WeekStrip from './WeekStrip.vue'
import SourceList from './SourceList.vue'
import type { Attempt, Course, GenerationJob, Material, Metric, Overview, Plan, Point, Quiz, Reviews, Source, Unit } from './types'

const props=withDefaults(defineProps<{learnerName?:string;maxUploadMb?:number}>(),{maxUploadMb:50})
const dateToday=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())
const selectedDay=ref(dateToday)
const tabIcons=[Layers3,FileText,Waypoints,CalendarDays,MessageSquare,Target,BookOpen,Clock3,Lightbulb]
function examDays(date:string){return Math.round((new Date(date+'T00:00:00+08:00').getTime()-new Date(dateToday+'T00:00:00+08:00').getTime())/86400000)}
type Tab = 'overview'|'materials'|'outline'|'study-plan'|'tutor'|'practice'|'mistakes'|'review'|'analytics'
const tabs: {id: Tab; title: string}[] = [{id:'overview',title:'课程概览'},{id:'materials',title:'课程资料'},{id:'outline',title:'章节与知识点'},{id:'study-plan',title:'学习计划'},{id:'tutor',title:'引用问答'},{id:'practice',title:'练习'},{id:'mistakes',title:'错题本'},{id:'review',title:'间隔复习'},{id:'analytics',title:'学习数据'}]
const courses=ref<Course[]>([]), selected=ref<Course|null>(null), tab=ref<Tab>('overview')
const error=ref(''),notice=ref(''),busy=ref(false),creating=ref(false),editing=ref(false),loading=ref(true)
const kbs=ref<KnowledgeBase[]>([])
const form=ref({name:'',exam_date:'',exam_name:'',weekly_minutes:300,target_score:null as number|null,syllabus:'',knowledge_base_id:''})
const overview=ref<Overview|null>(null), materials=ref<Material[]>([]), units=ref<Unit[]>([]), points=ref<Point[]>([])
const plan=ref<Plan|null>(null), quizzes=ref<Quiz[]>([]), mistakes=ref<Attempt[]>([]), reviews=ref<Reviews|null>(null)
const jobs=ref<Record<string,Job>>({}), generation=ref<GenerationJob|null>(null), sourcePreview=ref<Source[]>([])
const unitForm=ref({title:'',parent_id:'',ordinal:0,weight:1})
const pointForm=ref({title:'',description:'',unit_id:'',importance:1,mastery_state:'unknown'})
const mergeIds=ref<string[]>([]),assessmentPhase=ref('practice'),prePost=ref<{title:string;value:number|null;pre_sample_size:number;post_sample_size:number;insufficient_sample:boolean;definition:string}[]>([])
const selectedChunks=ref<string[]>([]), availableChunks=ref<(Source & {id:string})[]>([]), editingPoint=ref('')
const uploadInput=ref<HTMLInputElement|null>(null), materialType=ref('lecture')
const tutor=ref({question:'',mode:'explain',unit_id:'',knowledge_point_id:''}), answer=ref<ChatResponse|null>(null),draft=ref(''),asking=ref(false)
const quizForm=ref({type:'single',difficulty:'basic',count:3,unit_id:'',knowledge_point_id:'',include_explanation:true,multiple_sources:false})
const activeQuiz=ref<Quiz|null>(null), studentAnswer=ref(''), attempt=ref<Attempt|null>(null), confidence=ref(3), started=ref(0)
const shownCards=ref<string[]>([]),selectedErrors=ref<string[]>([])
const errorTags=['概念混淆','公式/步骤错误','关键词遗漏','审题错误','记忆不牢','资料理解错误','题目或解析可能有问题']
const confirmed=computed(()=>points.value.filter(p=>p.confirmed_at))
const courseDocuments=computed(()=>kbs.value.filter(k=>courses.value.some(c=>c.knowledge_base_id===k.id)).reduce((sum,k)=>sum+k.document_count,0))
const nextExam=computed(()=>courses.value.filter(c=>!c.exam_passed&&c.status==='active').sort((a,b)=>a.exam_date.localeCompare(b.exam_date))[0])
const datedTasks=computed(()=>plan.value?.tasks.filter(t=>t.scheduled_for===selectedDay.value&&t.status!=='skipped')||[])
const completedTasks=computed(()=>plan.value?.tasks.filter(t=>t.status==='completed').length||0)
const courseCoverage=computed(()=>{const total=plan.value?.tasks.filter(t=>t.status!=='skipped').length||0;return total?Math.round(completedTasks.value/total*100):0})
const names: Record<string,string>={materials:'资料数',knowledge_points:'已确认知识点',mastery:'知识点掌握率',quiz_count:'有效练习题',attempt_count:'作答数',accuracy:'练习正确率',repeat_error_rate:'错题复现率',plan_completion:'计划完成率',streak_days:'连续学习天数',citation_coverage:'回答引用覆盖率',unsupported_blocked:'无依据拒答数'}
const ratioKeys=new Set(['mastery','accuracy','repeat_error_rate','plan_completion','citation_coverage'])
function metricText(key:string,m:Metric){return m.value===null?'暂无样本':ratioKeys.has(key)?`${Math.round(m.value*100)}%`:String(m.value)}
const todayTasks=computed(()=>plan.value?.tasks.filter(t=>t.scheduled_for<=plan.value!.today&&t.status==='pending')||[])
let timer:ReturnType<typeof setInterval>|undefined,controller:AbortController|null=null,polling=false,requestVersion=0
function message(e:unknown){error.value=e instanceof Error?e.message:'请求失败'}
async function perform(action:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await action()}catch(e){message(e)}finally{busy.value=false}}
const base=()=>`/courses/${selected.value!.id}`
function navigate(course:Course|null,next:Tab='overview',replace=false){
  controller?.abort(); selected.value=course;tab.value=next;answer.value=null;draft.value='';activeQuiz.value=null;attempt.value=null;sourcePreview.value=[];generation.value=null;overview.value=null;selectedDay.value=dateToday
  units.value=[];points.value=[];materials.value=[];quizzes.value=[];mistakes.value=[];reviews.value=null;plan.value=null
  const path=course?`/courses/${course.id}${next==='overview'?'':'/'+next}`:'/courses'
  if(replace)history.replaceState(null,'',path);else history.pushState(null,'',path)
  if(course)void loadCourse().catch(message)
}
function changeTab(next:Tab){tab.value=next;history.pushState(null,'',`/courses/${selected.value!.id}${next==='overview'?'':'/'+next}`)}
async function readRoute(){
  const [,root,id,section]=location.pathname.split('/')
  if(root!=='courses') {navigate(null,'overview',true);return}
  const course=courses.value.find(c=>c.id===id)||null
  navigate(course,tabs.some(t=>t.id===section)?section as Tab:'overview',true)
}
async function loadCourse(){
  if(!selected.value)return
  const id=selected.value.id,version=++requestVersion
  const results=await Promise.all([api<Overview>(`/courses/${id}/overview`),api<Material[]>(`/courses/${id}/materials`),api<Unit[]>(`/courses/${id}/units`),api<Point[]>(`/courses/${id}/knowledge-points`),api<Plan>(`/courses/${id}/study-plan`),api<Quiz[]>(`/courses/${id}/quiz`),api<Attempt[]>(`/courses/${id}/mistakes`),api<Reviews>(`/courses/${id}/review/today`)])
  if(selected.value?.id!==id||version!==requestVersion)return
  ;[overview.value,materials.value,units.value,points.value,plan.value,quizzes.value,mistakes.value,reviews.value]=results
  prePost.value=await api(`/courses/${id}/metrics/pre-post`)
}
async function refreshCourses(){courses.value=await api<Course[]>('/courses');kbs.value=await api<KnowledgeBase[]>('/knowledge-bases')}
function setup(course?:Course){editing.value=!!course;creating.value=true;form.value=course?{name:course.name,exam_date:course.exam_date,exam_name:course.exam_name,weekly_minutes:course.weekly_minutes,target_score:course.target_score,syllabus:course.syllabus,knowledge_base_id:course.knowledge_base_id}:{name:'',exam_date:'',exam_name:'',weekly_minutes:300,target_score:null,syllabus:'',knowledge_base_id:''}}
async function saveCourse(){await perform(async()=>{
  const {knowledge_base_id,...fields}=form.value
  const body={...fields,exam_name:fields.exam_name||null,target_score:fields.target_score==null?null:Number(fields.target_score)}
  const c=await api<Course>(editing.value?base():'/courses',{method:editing.value?'PATCH':'POST',body:JSON.stringify(editing.value?body:{...body,knowledge_base_id:knowledge_base_id||null})})
  await refreshCourses();creating.value=false;navigate(c);notice.value='课程与基础计划已保存'
})}
async function removeCourse(){if(!selected.value||!confirm('删除课程会同时删除关联知识库、资料、练习及学习记录，确定继续？'))return;await perform(async()=>{await api(base(),{method:'DELETE'});await refreshCourses();navigate(null)})}
async function upload(event:Event){
  const files=(event.target as HTMLInputElement).files
  if(!files?.length||!selected.value)return
  const list=Array.from(files),courseId=selected.value.id,type=materialType.value
  await perform(async()=>{
    const oversized=list.find(file=>file.size>props.maxUploadMb*1024*1024)
    if(oversized)throw new Error(`“${oversized.name}”超过 ${props.maxUploadMb} MB 上传上限，请压缩或拆分后重试。`)
    let submitted=0
    try{
      for(const file of list){
        const body=new FormData();body.append('file',file);body.append('material_type',type)
        await api(`/courses/${courseId}/materials/upload`,{method:'POST',body});submitted++
      }
      notice.value=`${submitted} 份资料已进入解析队列，完成前不会用于问答和练习。`
    }catch(reason){
      if(reason instanceof ApiError&&reason.status===0)throw new Error('上传连接中断。请确认 SSH 转发窗口保持打开，刷新资料列表检查是否已提交，再重试上传。')
      throw reason
    }finally{
      if(selected.value?.id===courseId&&submitted)await loadCourse()
    }
  })
  if(uploadInput.value)uploadInput.value.value=''
}

async function retryMaterial(m:Material){await perform(async()=>{await api(`/materials/${m.id}/retry`,{method:'POST'});await loadCourse()})}
async function metadata(m:Material,key:string,value:string){await perform(async()=>{await api(base()+`/materials/${m.id}`,{method:'PATCH',body:JSON.stringify({type:m.material_metadata.type||'lecture',unit_id:m.material_metadata.unit_id||null,trust_note:m.material_metadata.trust_note||'',[key]:value||null})});await loadCourse()})}
async function inspect(m:Material){sourcePreview.value=[];await perform(async()=>{const chunks=await api<(Source & {id:string})[]>(`/documents/${m.id}/chunks`);sourcePreview.value=chunks.map(c=>({...c,document_id:m.id,document_name:m.name}));if(m.parse_status==='vision_pending'||m.status==='vision_pending'){const detail=await api<Material>(`/materials/${m.id}/parse-status`);sourcePreview.value=(detail.parse_metadata.pages||[]).map(p=>({...p,document_id:m.id,document_name:m.name}))}})}
async function addUnit(){await perform(async()=>{await api(base()+'/units',{method:'POST',body:JSON.stringify({...unitForm.value,parent_id:unitForm.value.parent_id||null})});unitForm.value.title='';await loadCourse()})}
async function mergePoints(){if(mergeIds.value.length<2)return;const title=prompt('合并后的知识点名称');if(!title?.trim())return;await perform(async()=>{await api(base()+'/knowledge-points/merge',{method:'POST',body:JSON.stringify({point_ids:mergeIds.value,title})});mergeIds.value=[];await loadCourse()})}
async function splitPoint(p:Point){const text=prompt('输入拆分后的名称，用中文或英文逗号分隔。原来源将保留到每个新知识点，可再编辑调整。');if(!text)return;const titles=text.split(/[,，]/).map(t=>t.trim()).filter(Boolean);await perform(async()=>{await api(`/knowledge-points/${p.id}/split`,{method:'POST',body:JSON.stringify({titles})});await loadCourse()})}
async function editUnit(u:Unit){const title=prompt('章节名称',u.title);if(!title?.trim())return;await perform(async()=>{await api(`/course-units/${u.id}`,{method:'PATCH',body:JSON.stringify({title,parent_id:u.parent_id,ordinal:u.ordinal,weight:u.weight})});await loadCourse()})}
async function loadChunks(){if(!selected.value)return;const all=await Promise.all(materials.value.filter(m=>m.status==='ready').map(async m=>(await api<(Source&{id:string})[]>(`/documents/${m.id}/chunks`)).map(c=>({...c,document_id:m.id,document_name:m.name}))));availableChunks.value=all.flat()}
async function savePoint(){await perform(async()=>{await api(editingPoint.value?`/knowledge-points/${editingPoint.value}`:base()+'/knowledge-points',{method:editingPoint.value?'PATCH':'POST',body:JSON.stringify({...pointForm.value,unit_id:pointForm.value.unit_id||null,chunk_ids:selectedChunks.value})});pointForm.value={title:'',description:'',unit_id:'',importance:1,mastery_state:'unknown'};selectedChunks.value=[];editingPoint.value='';await loadCourse()})}
async function editPoint(p:Point){await perform(async()=>{pointForm.value={title:p.title,description:p.description,unit_id:p.unit_id||'',importance:p.importance,mastery_state:p.mastery_state};editingPoint.value=p.id;await loadChunks();const rows=await api<(Source&{id:string})[]>(`/knowledge-points/${p.id}/sources`);selectedChunks.value=rows.map(r=>r.id)})}
async function pointAction(p:Point,action:string){await perform(async()=>{await api(`/knowledge-points/${p.id}${action==='confirm'?'/confirm':''}`,{method:action==='confirm'?'POST':'DELETE'});await loadCourse()})}
async function suggest(){await perform(async()=>{await api(base()+'/knowledge-points/suggest',{method:'POST'});await loadCourse();notice.value='建议尚未进入正式计划，请确认、编辑或忽略'})}
async function taskAction(id:string,status:string,minutes?:number){await perform(async()=>{await api(`/study-tasks/${id}/complete`,{method:'POST',body:JSON.stringify({status,minutes})});await loadCourse()})}
async function adjustTask(id:string,current:number){const value=prompt('调整任务分钟数（受当天学习预算约束）',String(current));if(value===null)return;const minutes=Number(value);if(!Number.isInteger(minutes)||minutes<1){error.value='请输入正整数分钟';return}await taskAction(id,'pending',minutes)}
async function rebuild(){await perform(async()=>{await api(base()+'/study-plan/rebuild',{method:'POST'});await loadCourse();notice.value='未开始任务已重排，已完成记录保留'})}
async function ask(){if(!tutor.value.question.trim()||asking.value)return;asking.value=true;error.value='';answer.value=null;draft.value='';controller=new AbortController();try{answer.value=await streamChat({...tutor.value,unit_id:tutor.value.unit_id||null,knowledge_point_id:tutor.value.knowledge_point_id||null,request_id:crypto.randomUUID()},controller.signal,text=>draft.value+=text,base()+'/tutor/stream');await loadCourse()}catch(e){if(!(e instanceof DOMException&&e.name==='AbortError'))message(e)}finally{asking.value=false;draft.value=''}}
async function generate(){await perform(async()=>{generation.value=await api(base()+'/quiz/generate',{method:'POST',body:JSON.stringify({...quizForm.value,unit_id:quizForm.value.unit_id||null,knowledge_point_id:quizForm.value.knowledge_point_id||null,request_id:crypto.randomUUID()})})})}
function startQuiz(q:Quiz){assessmentPhase.value='practice';activeQuiz.value=q;studentAnswer.value='';attempt.value=null;selectedErrors.value=[];started.value=Date.now();changeTab('practice')}
async function submit(){if(!activeQuiz.value||!studentAnswer.value.trim())return;await perform(async()=>{attempt.value=await api(`/quiz/${activeQuiz.value!.id}/attempt`,{method:'POST',body:JSON.stringify({answer:studentAnswer.value,request_id:crypto.randomUUID(),duration_ms:Date.now()-started.value,confidence:confidence.value,assessment_phase:assessmentPhase.value,error_tags:[]})});selectedErrors.value=attempt.value?.error_tags||[];await loadCourse()})}
async function setErrors(id:string,tags:string[]){await perform(async()=>{await api(`/attempts/${id}/error-tags`,{method:'PATCH',body:JSON.stringify({error_tags:tags})});await loadCourse();notice.value='已保存你确认的错因'})}
async function reviewStatus(q:Quiz,status:string){await perform(async()=>{await api(`/quiz/${q.id}/review-status`,{method:'PATCH',body:JSON.stringify({status})});await loadCourse()})}
async function feedback(q:Quiz){await perform(async()=>{await api(`/quiz/${q.id}/feedback`,{method:'POST',body:JSON.stringify({reason:'题目有问题'})});notice.value='已记录题目反馈'})}
async function grade(id:string,grade:string){await perform(async()=>{const card=await api<{due_at:string}>(`/review-cards/${id}/grade`,{method:'POST',body:JSON.stringify({grade,request_id:crypto.randomUUID()})});notice.value=`复习已记录，下次到期：${new Date(card.due_at+'Z').toLocaleString()}`;await loadCourse()})}
async function poll(){if(polling||!selected.value)return;polling=true;try{
  const id=selected.value.id
  for(const m of materials.value.filter(m=>['queued','processing'].includes(m.status))){if(m.job_id)jobs.value[m.id]=await api<Job>(`/jobs/${m.job_id}`)}
  const wasGenerating=!!generation.value&&['queued','running'].includes(generation.value.status)
  if(wasGenerating)generation.value=await api(`/learning-jobs/${generation.value!.id}`)
  if(materials.value.some(m=>['queued','processing'].includes(m.status))||(wasGenerating&&generation.value?.status==='completed')){if(selected.value?.id===id)await loadCourse()}
}catch(e){message(e)}finally{polling=false}}
onMounted(async()=>{try{await refreshCourses();await readRoute();timer=setInterval(poll,4000);window.addEventListener('popstate',readRoute)}catch(e){message(e)}finally{loading.value=false}})
onUnmounted(()=>{clearInterval(timer);controller?.abort();window.removeEventListener('popstate',readRoute)})
</script>

<template>
<main class="learning-workspace">
  <div v-if="error" class="learning-banner error" role="alert">{{ error }}<button @click="error=''" aria-label="关闭错误">×</button></div>
  <div v-if="notice" class="learning-banner" role="status">{{ notice }}</div>
  <p v-if="loading">正在读取课程…</p>
  <template v-else-if="!selected">
    <div class="studio-list-layout"><div class="studio-main">
      <header class="studio-hero">
        <div class="hero-copy"><span class="studio-kicker"><i/> SHIYI · LEARNING JOURNAL</span><p class="hero-greeting">你好，{{ learnerName || '学习者' }}。今天想拾起什么？</p><h1>让每一点好奇，<br>都有<span>回响<svg viewBox="0 0 150 12" aria-hidden="true"><path d="M3 8Q62-1 147 6M14 11Q88 4 135 9" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg></span>。</h1><p class="hero-description">把散落的资料，整理成自己的理解。<br>从一门课程开始，慢慢走向下一个目标。</p><button class="btn primary hero-create" @click="setup()"><Plus :size="16"/>开启一门课程 <ArrowUpRight :size="17"/></button></div>
        <div class="journal-art" aria-hidden="true"><span class="art-spark spark-one">✳</span><span class="art-spark spark-two">＋</span><div class="art-note"><span>一点一滴，<br>都是进步。</span><svg viewBox="0 0 80 35"><path d="M3 9q20 28 48 1m-8-5 12 3-3 12" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/></svg></div><div class="art-book book-back"></div><div class="art-book book-front"><span class="book-edition">THE PERSONAL<br>LEARNING COLLECTION</span><BookOpen :size="49" :stroke-width="1"/><strong>拾意</strong><span class="book-subtitle">把知识，学成自己的。</span><span class="book-footer">STUDY · PRACTICE · REMEMBER <i>01</i></span></div><span class="art-caption">a little wiser, every day.</span></div>
      </header>
      <div class="journal-statline"><div><span class="statline-icon"><BookOpen :size="17"/></span><strong>{{ String(courses.length).padStart(2,'0') }}</strong><span>收纳的课程</span></div><div><span class="statline-icon"><FileText :size="17"/></span><strong>{{ String(courseDocuments).padStart(2,'0') }}</strong><span>课程资料</span></div><div><span class="statline-icon"><CalendarDays :size="17"/></span><strong>{{ nextExam?examDays(nextExam.exam_date):'—' }}</strong><span>{{ nextExam?'天后迎接最近的考试':'等待一个新目标' }}</span></div></div>
      <section class="course-shelf"><div class="shelf-heading"><div><span class="studio-kicker">YOUR COLLECTION</span><h2>我的课程书架<span>{{ courses.length }} COURSES</span></h2></div><button class="shelf-add" @click="setup()"><Plus :size="16"/>新课程</button></div>
        <div v-if="courses.length" class="course-grid"><button v-for="(course,index) in courses" :key="course.id" class="course-card" :class="'cover-tone-'+index%4" @click="navigate(course)"><div class="course-cover"><span class="cover-index">{{ String(index+1).padStart(2,'0') }} / STUDY NOTES</span><span class="cover-ribbon" aria-hidden="true"/><BookOpen class="cover-icon" :size="30" :stroke-width="1.2"/><h3>{{ course.name }}</h3><p>{{ course.syllabus || '每一次理解，都让知识更近一点。' }}</p><span class="cover-bottom">{{ course.exam_passed?'AFTER THE EXAM':'A WORK IN PROGRESS' }}<ArrowUpRight :size="19"/></span></div><div class="course-card-meta"><span><CalendarDays :size="13"/>{{ course.exam_date }}</span><span>{{ course.exam_passed?'考后复盘':`${examDays(course.exam_date)} 天后考试` }}</span></div><div class="course-card-foot"><span>{{ course.weekly_minutes }} 分钟 / 周</span><strong>继续学习 <ArrowRight :size="13"/></strong></div></button><button class="course-new-card" @click="setup()"><span><Plus :size="25" :stroke-width="1.2"/></span><h3>下一段探索</h3><p>给新的好奇心，<br>留一个位置。</p><small>创建课程 <ArrowUpRight :size="13"/></small></button></div>
        <article v-else class="first-chapter"><div class="first-chapter-symbol"><BookOpen :size="32" :stroke-width="1.2"/><span>01</span></div><div><span class="studio-kicker">EVERY STORY STARTS SOMEWHERE</span><h3>你的第一章，还等着被翻开。</h3><p>只要一个课程名称和考试日期。已有的知识库，也能直接成为这门课的资料。</p><button class="text-button" @click="setup()">创建第一门课程 <ArrowRight :size="15"/></button></div></article>
      </section>
      <footer class="studio-page-note"><span>✳</span> 学习不是收集更多，而是理解更深。<small>MADE FOR YOUR OWN PACE</small></footer>
