    <section v-if="tab==='outline'" class="learning-stack">
      <div class="learning-columns"><form class="learning-card learning-form" @submit.prevent="addUnit"><h2>章节</h2><div v-for="u in units" :key="u.id" class="learning-row"><span>{{ u.parent_id?'↳ ':'' }}{{ u.title }}</span><small>权重 {{ u.weight }}</small><button type="button" class="btn secondary" @click="editUnit(u)">重命名</button></div><label>章节名称<input v-model="unitForm.title" required maxlength="200"/></label><label>上级章节<select v-model="unitForm.parent_id"><option value="">顶级章节</option><option v-for="u in units" :key="u.id" :value="u.id">{{ u.title }}</option></select></label><button class="btn primary" :disabled="busy">添加章节</button></form>
      <form class="learning-card learning-form" @submit.prevent="savePoint"><h2>{{ editingPoint?'编辑知识点':'添加知识点' }}</h2><label>名称<input v-model="pointForm.title" required maxlength="200"/></label><label>说明<textarea v-model="pointForm.description"/></label><label>所属章节<select v-model="pointForm.unit_id"><option value="">未指定</option><option v-for="u in units" :key="u.id" :value="u.id">{{ u.title }}</option></select></label><label>重要程度（1–5）<input v-model.number="pointForm.importance" type="number" min="1" max="5"/></label><label>掌握状态<select v-model="pointForm.mastery_state"><option value="unknown">未知</option><option value="learning">学习中</option><option value="mastered">已掌握（自评）</option></select></label><button type="button" class="btn secondary" @click="loadChunks().catch(message)">选择关联原文片段</button><div v-if="availableChunks.length" class="learning-chunk-picker"><label v-for="c in availableChunks" :key="c.id"><input v-model="selectedChunks" type="checkbox" :value="c.id"/>{{ c.document_name }} · {{ c.page_label||c.page }} · {{ c.text.slice(0,100) }}</label></div><button class="btn primary" :disabled="busy">保存知识点</button></form></div>
      <article class="learning-card"><div class="learning-row"><h2>知识点大纲</h2><button class="btn secondary" :disabled="busy||mergeIds.length<2" @click="mergePoints">合并所选知识点</button><button class="btn secondary" :disabled="busy" @click="suggest">从资料建议知识点</button></div><p>待确认建议不会加入正式计划。可以编辑建议、关联原文，再确认或忽略。</p><article v-for="p in points" :key="p.id" class="learning-point"><div><h3><input v-model="mergeIds" type="checkbox" :value="p.id" aria-label="选择要合并的知识点"/> {{ p.title }}</h3><p>{{ p.description }}</p><small>{{ p.confirmed_at?'已确认':'待确认建议' }} · {{ {unknown:'未知',learning:'学习中',mastered:'已掌握（自评）'}[p.mastery_state] }}</small></div><div class="learning-actions"><button v-if="!p.confirmed_at" class="btn primary" :disabled="busy" @click="pointAction(p,'confirm')">确认</button><button class="btn secondary" @click="editPoint(p)">编辑</button><button class="btn secondary" :disabled="busy" @click="splitPoint(p)">拆分</button><button class="btn secondary" @click="perform(async()=>{sourcePreview=await api(`/knowledge-points/${p.id}/sources`)})">查看来源</button><button class="btn secondary" :disabled="busy" @click="pointAction(p,'delete')">{{ p.confirmed_at?'删除':'忽略' }}</button></div></article><SourceList :sources="sourcePreview"/></article>
    </section>
    <section v-if="tab==='study-plan'" class="learning-stack"><article class="learning-card"><div class="learning-row"><div><h2>学习计划</h2><p>每日预算 {{ plan?.daily_budget_minutes }} 分钟 · 今日 {{ plan?.today }} · 当前待办 {{ todayTasks.length }} 项</p></div><button class="btn secondary" :disabled="busy" @click="rebuild">重建未开始任务</button></div><p>仅使用已确认知识点；没有知识点时按章节或资料安排，已有完成记录不会被重写。</p></article><article v-for="task in plan?.tasks" :key="task.id" class="learning-card learning-row"><div><h3>{{ task.title }}</h3><small>{{ task.scheduled_for }} · {{ task.minutes }} 分钟 · {{ {pending:'待完成',completed:'已完成',skipped:'已跳过',blocked:'无法完成'}[task.status] }}</small></div><div v-if="task.status==='pending'" class="learning-actions"><button class="btn primary" :disabled="busy" @click="taskAction(task.id,'completed')">完成</button><button class="btn secondary" :disabled="busy" @click="taskAction(task.id,'skipped')">跳过</button><button class="btn secondary" :disabled="busy" @click="adjustTask(task.id,task.minutes)">调整时长</button><button class="btn secondary" :disabled="busy" @click="taskAction(task.id,'blocked')">无法完成</button></div></article></section>
    <section v-if="tab==='tutor'" class="learning-stack"><form class="learning-card learning-form" @submit.prevent="ask"><h2>围绕课程资料提问</h2><p>检索范围固定为当前课程。没有证据时会提示“当前资料未覆盖”。</p><div class="learning-actions"><select v-model="tutor.mode" aria-label="学习模式"><option value="explain">讲解</option><option value="example">举例</option><option value="compare">对比</option><option value="practice">练习引导</option></select><select v-model="tutor.unit_id" aria-label="问答章节"><option value="">全部章节</option><option v-for="u in units" :key="u.id" :value="u.id">{{ u.title }}</option></select><select v-model="tutor.knowledge_point_id" aria-label="问答知识点"><option value="">全部知识点</option><option v-for="p in confirmed" :key="p.id" :value="p.id">{{ p.title }}</option></select></div><textarea v-model="tutor.question" required rows="4" maxlength="7000" placeholder="例如：对比卷积神经网络和循环神经网络的适用场景"/><button class="btn primary" :disabled="asking">{{ asking?'正在检索与生成…':'提问' }}</button><button v-if="asking" type="button" class="btn secondary" @click="controller?.abort()">停止</button></form><article v-if="answer||draft" class="learning-card"><h2>{{ asking?'生成中 · 最终答案将经过证据检查':'课程回答' }}</h2><p class="source-text">{{ answer?.answer||draft }}</p><SourceList v-if="answer" :sources="answer.citations"/><button v-if="answer" class="btn secondary" @click="changeTab('practice')">围绕课程生成练习</button></article></section>
    <section v-if="tab==='practice'" class="learning-stack"><form class="learning-card learning-form" @submit.prevent="generate"><h2>基于资料生成练习</h2><p>生成结果为待核对草稿，规则校验不能替代人工检查；不是正式试题或成绩认证。</p><div class="learning-actions"><select v-model="quizForm.type" aria-label="题型"><option value="single">单选</option><option value="boolean">判断</option><option value="short">简答</option></select><select v-model="quizForm.difficulty" aria-label="难度"><option value="basic">基础</option><option value="applied">应用</option><option value="comprehensive">综合</option></select><input v-model.number="quizForm.count" type="number" min="1" max="20" aria-label="题目数量"/><select v-model="quizForm.unit_id" aria-label="出题章节"><option value="">全部章节</option><option v-for="u in units" :key="u.id" :value="u.id">{{ u.title }}</option></select><select v-model="quizForm.knowledge_point_id" aria-label="出题知识点"><option value="">全部知识点</option><option v-for="p in confirmed" :key="p.id" :value="p.id">{{ p.title }}</option></select></div><label><input v-model="quizForm.multiple_sources" type="checkbox"/>允许同批练习使用多个资料</label><button class="btn primary" :disabled="busy||!!(generation&&['queued','running'].includes(generation.status))">生成练习草稿</button><p v-if="generation" role="status">出题任务：{{ {queued:'排队中',running:'生成中',completed:'已完成',failed:'失败',cancelled:'已取消'}[generation.status] }} · 已生成 {{ generation.result?.generated||0 }} 题。{{ generation.error||generation.result?.note }}</p><p v-for="(reason,index) in generation?.result?.skipped" :key="index">已跳过：{{ reason }}</p><div v-if="generation" class="learning-actions"><button v-if="['queued','running'].includes(generation.status)" type="button" class="btn secondary" @click="perform(async()=>{generation=await api(`/learning-jobs/${generation!.id}/cancel`,{method:'POST'})})">取消任务</button><button v-if="['failed','cancelled'].includes(generation.status)" type="button" class="btn secondary" @click="perform(async()=>{generation=await api(`/learning-jobs/${generation!.id}/retry`,{method:'POST'})})">重试任务</button></div></form>
      <article v-if="activeQuiz" class="learning-card learning-form"><span class="learning-chip">{{ activeQuiz.status==='draft'?'待核对草稿':'已人工核对' }}</span><h2>{{ activeQuiz.stem }}</h2><template v-if="activeQuiz.type==='single'"><label v-for="option in activeQuiz.options" :key="option" class="learning-option"><input v-model="studentAnswer" type="radio" :value="option" :disabled="!!attempt"/>{{ option }}</label></template><template v-else-if="activeQuiz.type==='boolean'"><label v-for="option in ['正确','错误']" :key="option" class="learning-option"><input v-model="studentAnswer" type="radio" :value="option" :disabled="!!attempt"/>{{ option }}</label></template><textarea v-else v-model="studentAnswer" rows="4" placeholder="写出你的答案，再对照原文自查" :disabled="!!attempt"/><label>练习用途<select v-model="assessmentPhase" :disabled="!!attempt"><option value="practice">日常练习</option><option value="pre">知识点前测</option><option value="post">知识点后测（必须使用不同题目）</option></select></label><label>作答信心（1–5）<input v-model.number="confidence" type="number" min="1" max="5"/></label><button v-if="!attempt" class="btn primary" :disabled="busy||!studentAnswer.trim()" @click="submit">提交答案</button><div v-if="attempt"><h3>{{ attempt.is_correct===null?'待自查，不计入正确率':attempt.is_correct?'规则比对：正确':'规则比对：未答对' }}</h3><p>{{ attempt.feedback }}</p><p>标准答案：{{ attempt.standard_answer }}</p><p class="source-text">{{ attempt.explanation }}</p><SourceList :sources="attempt.citations"/><p v-if="attempt.suggested_error_tags.length">系统建议（未写入你的错因）：{{ attempt.suggested_error_tags.join('、') }}</p><div class="learning-actions"><label v-for="tag in errorTags" :key="tag"><input v-model="selectedErrors" type="checkbox" :value="tag"/>{{ tag }}</label></div><button class="btn secondary" :disabled="busy" @click="setErrors(attempt.id,selectedErrors)">保存我确认的错因</button></div><button class="btn secondary" @click="feedback(activeQuiz)">反馈题目有问题</button></article>
      <article v-for="q in quizzes" :key="q.id" class="learning-card"><div class="learning-row"><h3>{{ q.stem }}</h3><span>{{ {draft:'待核对',approved:'已核对',rejected:'已拒绝',retired:'已停用'}[q.status] }}</span></div><div class="learning-actions"><button v-if="!['rejected','retired'].includes(q.status)" class="btn primary" @click="startQuiz(q)">开始练习</button><details><summary>检查标准答案与来源</summary><p>{{ q.answer }}</p><p>{{ q.explanation }}</p><SourceList :sources="q.citations"/><button class="btn secondary" :disabled="busy" @click="reviewStatus(q,'approved')">已核对，批准</button><button class="btn secondary" :disabled="busy" @click="reviewStatus(q,'rejected')">拒绝此题</button></details></div></article>
    </section>
    <section v-if="tab==='mistakes'" class="learning-stack"><article class="learning-card"><h2>错题本</h2><p>仅展示来源仍有效的错题。系统建议错因需要你确认，才能写入记录。</p><p v-if="!mistakes.length">目前没有错题记录。</p></article><article v-for="m in mistakes" :key="m.id" class="learning-card"><h3>{{ m.quiz?.stem }}</h3><p>你的答案：{{ m.answer }}</p><p>参考答案：{{ m.quiz?.answer }}</p><p>{{ m.quiz?.explanation }}</p><SourceList :sources="m.quiz?.citations||[]"/><div class="learning-actions"><label v-for="tag in errorTags" :key="tag"><input v-model="m.error_tags" type="checkbox" :value="tag"/>{{ tag }}</label></div><div class="learning-actions"><button class="btn secondary" :disabled="busy" @click="setErrors(m.id,m.error_tags)">保存错因</button><button v-if="m.quiz" class="btn primary" @click="startQuiz(m.quiz)">再做一次</button></div></article></section>
    <section v-if="tab==='review'" class="learning-stack"><article class="learning-card"><h2>今日间隔复习</h2><p>到期 {{ reviews?.due_count }} 张 · 今日剩余预算 {{ reviews?.remaining_minutes }} 分钟 · 每卡预计 5 分钟</p><p>Leitner 间隔：1、2、4、7、14、30 天。记得升一级，太简单升两级，模糊降一级，不会回到第一级。</p><p v-if="!reviews?.cards.length">今日预算内暂无到期卡片。可以完成学习任务，或到错题本主动重练。</p></article><article v-for="card in reviews?.cards" :key="card.id" class="learning-card"><span class="learning-chip">第 {{ card.level }} 级</span><h3>{{ card.quiz.stem }}</h3><ul v-if="card.quiz.type==='single'"><li v-for="option in card.quiz.options" :key="option">{{ option }}</li></ul><button class="btn secondary" @click="shownCards.push(card.id)">回忆后查看答案</button><div v-if="shownCards.includes(card.id)"><p>{{ card.quiz.answer }}</p><p>{{ card.quiz.explanation }}</p><SourceList :sources="card.quiz.citations"/><div class="learning-actions"><button v-for="g in [{id:'easy',text:'太简单'},{id:'remember',text:'记得'},{id:'fuzzy',text:'模糊'},{id:'forgot',text:'不会'}]" :key="g.id" class="btn secondary" :disabled="busy" @click="grade(card.id,g.id)">{{ g.text }}</button></div></div></article></section>
    <section v-if="tab==='analytics'" class="learning-stack"><article class="learning-card"><div class="learning-row"><div><h2>学习过程与质量数据</h2><p>统计范围：当前课程和当前有效资料版本。小样本只展示过程，不代表考试成绩提升。</p></div><a class="btn secondary" :href="`${API_BASE}${base()}/metrics/export`" download>导出学习数据</a></div></article><div class="learning-metrics"><article v-for="(m,key) in overview?.metrics" :key="key" class="learning-card"><small>{{ names[key]||key }}</small><strong>{{ metricText(key,m) }}</strong><p>{{ m.definition }}</p><small>样本量：{{ m.sample_size }}{{ m.insufficient_sample?' · 样本不足':'' }}</small><small>{{ m.period.from }} — {{ m.period.to }}</small><small>口径 {{ m.definition_version }}</small></article></div><article v-if="prePost.length" class="learning-card"><h2>同知识点前后测</h2><div v-for="item in prePost" :key="item.title" class="learning-point"><div><h3>{{ item.title }}</h3><p>{{ item.value===null?'尚无可比较的前后测样本':`正确率变化 ${(item.value*100).toFixed(1)} 个百分点` }}</p><small>前测 {{ item.pre_sample_size }} 题 · 后测 {{ item.post_sample_size }} 题{{ item.insufficient_sample?' · 样本不足':'' }}</small><p>{{ item.definition }}</p></div></div></article><button class="btn secondary" @click="removeCourse">删除课程及其资料和学习记录</button></section>
  </template>
  <div v-if="creating" class="modal-backdrop" @click.self="creating=false"><form class="modal learning-form learning-setup" role="dialog" aria-modal="true" aria-labelledby="course-setup-title" @submit.prevent="saveCourse"><h2 id="course-setup-title">{{ editing?'调整考试目标':'创建课程' }}</h2><label>课程名称 *<input v-model="form.name" required maxlength="120"/></label><label>考试日期 *<input v-model="form.exam_date" type="date" required/></label><details><summary>可选目标与现有资料</summary><div class="learning-form"><label>考试名称<input v-model="form.exam_name" placeholder="默认使用课程名称"/></label><label>目标分数<input v-model.number="form.target_score" type="number" min="0" max="1000"/></label><label>每周学习分钟数<input v-model.number="form.weekly_minutes" type="number" min="7" max="5040"/></label><label>考试范围<textarea v-model="form.syllabus"/></label><label v-if="!editing">关联已有个人知识库<select v-model="form.knowledge_base_id"><option value="">创建新的课程知识库</option><option v-for="kb in kbs.filter(k=>!k.organization_id&&k.role==='admin'&&!courses.some(c=>c.knowledge_base_id===k.id))" :key="kb.id" :value="kb.id">{{ kb.name }}（{{ kb.document_count }} 份资料）</option></select></label></div></details><p>仅名称和日期也能生成基础计划，后续可以补充目标并重建计划。</p><div class="learning-actions"><button type="button" class="btn secondary" @click="creating=false">取消</button><button class="btn primary" :disabled="busy">{{ busy?'保存中…':'保存课程与计划' }}</button></div></form></div>
</main>
</template>

